def dissoc(d, key):
    """
    Deletes the key from the dictionary and returns a new dictionary.
    """
    return {k: v for k, v in d.items() if k!= key}

def merge(left, right):
    return dict(left, **right)

def merge_with(fn, left, right):
    result = left.copy()
    for k in right:
        result[k] = fn(result.get(k, ()), right[k])
    return result
